import java.util.*;
import java.util.concurrent.*;
import java.util.concurrent.atomic.*;

public class Main {
    enum SendStatus { NEW, SENDING, CONFIRMED, RETURNED, UNKNOWN, FAILED }
    record Message(long seq, String id, String businessKey, String routingKey, String body) {}
    record ConfirmResult(SendStatus status, boolean routed) {}

    // 模拟 Broker 队列（含 delivery-limit 和 DLQ 绑定）
    static final class QueueBox {
        final String name;
        final Deque<Message> ready = new ArrayDeque<>();
        final Deque<Message> unacked = new ArrayDeque<>();
        final Map<String, Integer> deliveryCount = new HashMap<>();
        int deliveryLimit = 3;
        QueueBox dlq;
        QueueBox(String name) { this.name = name; }

        Message deliver() {
            if (ready.isEmpty()) return null;
            Message msg = ready.removeFirst();
            unacked.addLast(msg);
            deliveryCount.merge(msg.businessKey(), 1, Integer::sum);
            return msg;
        }
        void ack(Message msg) {
            unacked.remove(msg);
            deliveryCount.remove(msg.businessKey());
        }
        void nack(Message msg, boolean requeue) {
            unacked.remove(msg);
            int count = deliveryCount.getOrDefault(msg.businessKey(), 0);
            if (count >= deliveryLimit) {
                // 超过 delivery-limit → 自动死信化
                if (dlq != null) dlq.ready.addLast(msg);
            } else if (requeue) {
                ready.addFirst(msg);
            } else {
                if (dlq != null) dlq.ready.addLast(msg);
            }
        }
        void closeChannelAndRequeueUnacked() {
            while (!unacked.isEmpty()) ready.addFirst(unacked.removeLast());
        }
    }

    // 模拟 Broker：Exchange 路由 + 队列存储
    static final class Broker {
        final QueueBox orderQueue = new QueueBox("order.q");
        final QueueBox deadLetterQueue = new QueueBox("order.dlq");
        Broker() { orderQueue.dlq = deadLetterQueue; }

        ConfirmResult publish(Message msg, boolean mandatory, boolean confirmTimeout) {
            if (confirmTimeout) return new ConfirmResult(SendStatus.UNKNOWN, false);
            if (!"order.created".equals(msg.routingKey())) {
                // 不可路由：mandatory=true 返回 RETURNED；mandatory=false 静默丢弃
                return new ConfirmResult(mandatory ? SendStatus.RETURNED : SendStatus.CONFIRMED, false);
            }
            orderQueue.ready.addLast(msg);
            return new ConfirmResult(SendStatus.CONFIRMED, true);
        }
    }

    // 模拟消费者：幂等 + 分类重试 + DLQ
    static final class Consumer {
        final Set<String> processedKeys = new HashSet<>();
        int applied, duplicateSkipped, dlqCount;

        void handle(Broker broker, Message msg, String failureType) {
            switch (failureType) {
                case "business_fail" -> {
                    broker.orderQueue.nack(msg, false);  // 不可恢复 → DLQ
                    dlqCount++;
                }
                case "temp_fail" -> {
                    broker.orderQueue.nack(msg, true);   // 临时错误 → requeue 重试
                }
                default -> {
                    if (processedKeys.add(msg.businessKey())) applied++;
                    else duplicateSkipped++;
                    broker.orderQueue.ack(msg);            // 业务成功后 ack
                }
            }
        }
    }

    public static void main(String[] args) {
        Broker broker = new Broker();
        Consumer consumer = new Consumer();

        // 1. confirm 正常 + 路由成功
        ConfirmResult ok = broker.publish(
            new Message(1, "m1", "order-1001", "order.created", "create"), true, false);
        // 2. mandatory + 不可路由 → RETURNED
        ConfirmResult returned = broker.publish(
            new Message(2, "m2", "order-404", "order.missing", "bad route"), true, false);
        // 3. confirm 超时 → UNKNOWN
        ConfirmResult unknown = broker.publish(
            new Message(3, "m3", "order-1002", "order.created", "timeout"), true, true);

        // 4. ack 丢失 → Channel 关闭 → 重投 → 幂等跳过
        Message firstDelivery = broker.orderQueue.deliver();
        consumer.handle(broker, firstDelivery, null);
        broker.orderQueue.closeChannelAndRequeueUnacked(); // ack 未到达 → 回到 ready
        Message redelivery = broker.orderQueue.deliver();
        consumer.handle(broker, redelivery, null);          // 幂等跳过

        // 5. 不可恢复错误 → nack 到 DLQ
        broker.publish(new Message(4, "m4", "order-1003", "order.created", "poison"), true, false);
        Message poison = broker.orderQueue.deliver();
        consumer.handle(broker, poison, "business_fail");

        assert ok.status() == SendStatus.CONFIRMED && ok.routed();
        assert returned.status() == SendStatus.RETURNED && !returned.routed();
        assert unknown.status() == SendStatus.UNKNOWN;
        assert consumer.applied == 1;
        assert consumer.duplicateSkipped == 1;
        assert consumer.dlqCount == 1;
        assert broker.orderQueue.ready.isEmpty();
        assert broker.deadLetterQueue.ready.size() == 1;

        System.out.println("ok=" + ok.status() + ", returned=" + returned.status()
            + ", timeout=" + unknown.status());
        System.out.println("applied=" + consumer.applied + ", dup=" + consumer.duplicateSkipped
            + ", dlq=" + broker.deadLetterQueue.ready.size());
    }
}
